/**
 * Nuzlocke — Dev Notes Page
 *
 * Renders as a PS tab at view-devnotes. Pure client-side, no server state.
 */

import preact from "../../../js/lib/preact";
import { NzSprite } from "../components/primitives";
import { NzLoadingScreen } from "../components/layout";
import { PS } from "../../client-main";
import { Dex } from "../../battle-dex";

function SectionHeader({ color, children }: { color: 'fire' | 'water' | 'grass' | 'electric'; children: preact.ComponentChildren }) {
	return <div class={`nz-dn-section-header nz-dn-section-header-${color}`}>{children}</div>;
}

function SpriteRow({ pokemon }: { pokemon: string[] }) {
	return (
		<div class="nz-dn-sprite-row">
			{pokemon.map(p => (
				<NzSprite key={p} species={p} size={60} class="nz-dn-sprite" animate={false} />
			))}
		</div>
	);
}

function TrainerSprite({ sprite, alt }: { sprite: string; alt: string }) {
	const url = (window as any).Dex?.resolveAvatar(sprite) as string
		?? `https://play.pokemonshowdown.com/sprites/trainers/${sprite}.png`;
	return <img class="nz-dn-trainer" src={url} alt={alt} width={96} height={96} />;
}

let _spriteSheetReady = false;

export function DevNotesPage() {
	if (!(window as any).BattlePokedex) return <NzLoadingScreen />;

	if (!_spriteSheetReady) {
		const sheet = new Image();
		sheet.onload = () => { _spriteSheetReady = true; PS.update(); };
		sheet.src = `${Dex.resourcePrefix}sprites/pokemonicons-sheet.png?v21`;
		if (sheet.complete) {
			_spriteSheetReady = true;
		} else {
			return <NzLoadingScreen />;
		}
	}
	return (
		<div class="nz-dn-content">
			<div class="nz-dn-sections-grid">

				<section class="nz-dn-section">
					<SectionHeader color="fire">The Origin Story</SectionHeader>
					<div class="nz-dn-section-inner">
						<div class="nz-dn-text-col">
							<p>
								Thank you so much for playing my game!
							</p>
							<p>
								I've had this idea rolling around in my head for years now and only 
								recently figured out how to make it a reality. It started with enjoying nuzlockes 
								but just never having the motivation to start a new one. It's a 
								ten-plus-hour commitment you could lose in an instant, and a majority of 
								the time isn't even spent on the good stuff.
							</p>
							<p>
								I enjoyed the teambuilding and the difficult battles, but if I had to fight
								ten more Team Rocket grunts with four Zubats each just to progress to the
								sixth gym, I was going to end up on the news. And don't get me started on
								trying to grind up to level cap without hacking in rare candies.
							</p>
						</div>
						<div class="nz-dn-sprite-col">
							<div class="nz-dn-sprite-card">
								<div class="nz-dn-sprite-caption">"Go! My 14 underleveled zubats!"</div>
								<TrainerSprite sprite="teamrocketgruntm-gen3" alt="Team Rocket Grunt" />
								<SpriteRow pokemon={['Zubat', 'Zubat', 'Zubat']} />
							</div>
						</div>
					</div>
				</section>

				<section class="nz-dn-section">
					<SectionHeader color="water">Strategy Focused</SectionHeader>
					<div class="nz-dn-section-inner nz-dn-section-inner-flip">
						<div class="nz-dn-sprite-col">
							<div class="nz-dn-sprite-card">
								<SpriteRow pokemon={['Torchic', 'Mudkip', 'Treecko']} />
								<TrainerSprite sprite="steven" alt="Champion" />
								<div class="nz-dn-sprite-caption">"Hey wait, I still need that letter delivered!"</div>
							</div>
						</div>
						<div class="nz-dn-text-col">
							<p>
								This game is my best attempt to design a game purely for nuzlocke
								strategy. It's just getting your random encounters, making a team, and trying
								to beat the next major fight. No grinding, no filler fights, no scouring
								Bulbapedia trying to remember which strength puzzle they hid the Water Stone
								behind.
							</p>
						</div>
					</div>
				</section>

				<section class="nz-dn-section">
					<SectionHeader color="grass">Under the Hood</SectionHeader>
					<div class="nz-dn-section-inner">
						<div class="nz-dn-text-col">
							<p>
								If you're curious about how it all works, it's a heavily modified version of
								Pokémon Showdown, which is open source and — crucially — is the only full
								Pokémon battle simulation you can play in your browser that I was able to
								find. In addition to all of the custom web pages, I had to write the AI from
								scratch, as well as plot out all the encounters, items, and battles through
								each game scenario.
							</p>
							<p>
								Custom chat commands are used to handle the client/server communication, and
								just figuring out that was possible was the big step to making this work.
							</p>
						</div>
						<div class="nz-dn-sprite-col">
							<div class="nz-dn-sprite-card">
								<SpriteRow pokemon={['Rotom', 'Porygon2']} />
								<TrainerSprite sprite="scientist" alt="Scientist" />
								<div class="nz-dn-sprite-caption">"It's all spaghetti code of course."</div>
							</div>
						</div>
					</div>
				</section>

				<section class="nz-dn-section">
					<SectionHeader color="electric">What's Next</SectionHeader>
					<div class="nz-dn-section-inner nz-dn-section-inner-flip">
						<div class="nz-dn-sprite-col">
							<div class="nz-dn-sprite-card">
								<div class="nz-dn-sprite-caption">"That's right, I send out my SIXTH Garchomp!"</div>
								<TrainerSprite sprite="cynthia" alt="Champion" />
								<SpriteRow pokemon={['Garchomp', 'Rayquaza']} />
							</div>
						</div>
						<div class="nz-dn-text-col">
							<p>
								There's a lot of things I want to add eventually. Difficult ROM hacks like
								Emerald Kaizo, the rest of the mainline games, a custom scenario editor,
								and more.
							</p>
							<p>
								I'll keep adding content as long as you all keep playing, so have fun and 
								tell your friends about it!
							</p>
						</div>
					</div>
				</section>

			</div>
			<div class="nz-dn-footer">
				<button class="nz-btn nz-btn-primary nz-dn-footer-btn" onClick={() => (PS as any).leave('view-devnotes')}>Close</button>
			</div>
		</div>
	);
}
